INSERT INTO `roles` (`id`, `name`, `slug`, `description`, `is_system`, `can_view_all_branches`, `created_at`, `updated_at`) VALUES
(1, 'Administrator', 'admin', 'Full, implicit access to every module. Cannot be edited or deleted.', 1, 1, '2026-08-03 11:44:08', '2026-08-03 11:44:08'),
(2, 'Branch Manager', 'branch_manager', 'Runs day-to-day operations for a single branch.', 0, 0, '2026-08-03 11:44:08', '2026-08-03 11:44:08'),
(3, 'Staff', 'staff', 'General branch staff with read access to their own branch.', 0, 0, '2026-08-03 11:44:08', '2026-08-03 11:44:08'),
(4, 'Cashier', 'cashier', 'Records loan payments at the counter, including full settlements (which a Branch Manager must approve).', 0, 0, '2026-08-03 11:44:08', '2026-08-03 11:44:08'),
(5, 'Marketing Executive', 'marketing_executive', 'Sources customers and loan applications in the field.', 0, 0, '2026-08-03 11:44:08', '2026-08-03 11:44:08'),
(6, 'Finance Officer', 'finance_officer', 'Raises and executes routine finance requests and runs daily cash sessions for a single branch.', 0, 0, '2026-09-01 12:42:04', '2026-09-01 12:42:04'),
(7, 'Finance Manager', 'finance_manager', 'Company-wide finance authority: approves requests and transfers, issues and settles floats, signs off cash variances.', 0, 1, '2026-09-01 12:42:04', '2026-09-01 12:42:04'),
(8, 'Finance Administrator', 'finance_admin', 'Full Finance module control including approval-tier and threshold settings, plus read access to the accounting side.', 0, 1, '2026-09-01 12:42:04', '2026-09-01 12:42:04');
